1344			// accumulator for this iterator's configured category and QoS. All SSTable
1345			// iterators created by this Iterator will accumulate their stats to it as
1346			// they Close during iteration.
1347			IterStats: i.fc.SSTStatsCollector().Accumulator(
1348				uint64(uintptr(unsafe.Pointer(i))),
1349				i.opts.Category,
1350			),
