1354		// Determine the blob file mapping. We may need to combine the version's
1355		// BlobFileSet with blob files from ingestedFlushables in the memtable queue.
1356		var maxReadAmp int
1357		var versionBlobFiles *manifest.BlobFileSet
1358		if i.readState != nil {
1359			versionBlobFiles = &i.readState.current.BlobFiles
1360			maxReadAmp = i.readState.current.MaxReadAmp()
1361		} else if i.version != nil {
1362			versionBlobFiles = &i.version.BlobFiles
1363			maxReadAmp = i.version.MaxReadAmp()
1364		}
1365		if i.combinedBlobMapping.Init(
1366			versionBlobFiles, memtables,
1367		) {
1368			i.blobValueFetcher.Init(&i.combinedBlobMapping, i.fc, readEnv,
1369				blob.SuggestedCachedReaders(maxReadAmp))
1370		}
1371	
1372		internalOpts := internalIterOpts{
1373			readEnv:          sstable.ReadEnv{Block: readEnv},
1374			blobValueFetcher: &i.blobValueFetcher,
1375		}
1376		if i.opts.RangeKeyMasking.Filter != nil {
1377			internalOpts.boundLimitedFilter = &i.rangeKeyMasking
1378		}
1379		return internalOpts
1380	}
