 60	// NewPebbleDB opens a Pebble DB at the given directory using settings derived
 61	// from cfg.
 62	func NewPebbleDB(dir string, cfg *CommonConfig) DB {
 63		opts := &pebble.Options{
 64			CacheSize:                   cfg.CacheSize,
 65			Comparer:                    &cockroachkvs.Comparer,
 66			DisableWAL:                  cfg.DisableWAL,
 67			FormatMajorVersion:          pebble.FormatNewest,
 68			KeySchema:                   cockroachkvs.KeySchema.Name,
 69			KeySchemas:                  sstable.MakeKeySchemas(&cockroachkvs.KeySchema),
 70			L0CompactionThreshold:       2,
 71			L0StopWritesThreshold:       1000,
 72			LBaseMaxBytes:               64 << 20, // 64 MB
 73			MaxOpenFiles:                16384,
 74			MemTableSize:                64 << 20,
 75			MemTableStopWritesThreshold: 4,
 76			Merger: &pebble.Merger{
 77				Name: "cockroach_merge_operator",
 78			},
 79			CompactionConcurrencyRange: func() (int, int) {
 80				return 1, 3
 81			},
 82			DisableAutomaticCompactions: cfg.DisableAutoCompactions,
 83			Logger:                      cfg.Logger,
 84		}
 85		// Enable value separation. Note the minimum size of 512 means that only the
 86		// variant of the ycsb benchmarks that uses 1024 values will result in any
 87		// value separation.
 88		opts.ValueSeparationPolicy = func() pebble.ValueSeparationPolicy {
 89			return pebble.ValueSeparationPolicy{
 90				Enabled:                  true,
 91				MinimumSize:              512,
 92				MinimumMVCCGarbageSize:   32,
 93				MaxBlobReferenceDepth:    10,
 94				RewriteMinimumAge:        5 * time.Minute,
 95				GarbageRatioLowPriority:  0.10, // 10% garbage
 96				GarbageRatioHighPriority: 0.30, // 30% garbage
 97			}
 98		}
 99	
100		// Running the tool should not start compactions due to garbage.
101		opts.CompactionGarbageFractionForMaxConcurrency = func() float64 {
102			return -1.0
103		}
104		for i := 0; i < len(opts.Levels); i++ {
105			l := &opts.Levels[i]
106			l.BlockSize = 32 << 10       // 32 KB
107			l.IndexBlockSize = 256 << 10 // 256 KB
108		}
109		opts.ApplyTableFilterPolicy(func() pebble.DBTableFilterPolicy { return pebble.DBTableFilterPolicyProgressive })
110		opts.FlushSplitBytes = opts.TargetFileSizes[0]
111	
112		opts.EnsureDefaults()
113	
114		if cfg.Verbose {
115			lel := pebble.MakeLoggingEventListener(nil)
116			opts.EventListener = &lel
117			opts.EventListener.TableDeleted = nil
118			opts.EventListener.TableIngested = nil
119			opts.EventListener.WALCreated = nil
120			opts.EventListener.WALDeleted = nil
121		}
122	
123		if cfg.PathToLocalSharedStorage != "" {
124			opts.RemoteStorage = remote.MakeSimpleFactory(map[remote.Locator]remote.Storage{
125				// Store all shared objects on local disk, for convenience.
126				remote.MakeLocator(""): remote.NewLocalFS(cfg.PathToLocalSharedStorage, vfs.Default),
127			})
128			opts.CreateOnShared = remote.CreateOnSharedAll
129			if cfg.SecondaryCacheSize != 0 {
130				opts.SecondaryCacheSizeBytes = cfg.SecondaryCacheSize
131			}
132		}
133	
134		p, err := pebble.Open(dir, opts)
135		if err != nil {
136			log.Fatal(err)
137		}
138		if cfg.PathToLocalSharedStorage != "" {
139			if err := p.SetCreatorID(1); err != nil {
140				log.Fatal(err)
141			}
142		}
143		db := pebbleDB{d: p}
144		if cfg.Ballast > 0 {
145			db.ballast = make([]byte, cfg.Ballast)
146		}
147		return db
148	}
