250	// init inserts y.cfg.InitialKeys into db (if > 0) and waits for compactions
251	// to stabilize. It does not start any worker goroutines.
252	func (y *ycsb) init(db DB) {
253		if y.cfg.InitialKeys <= 0 {
254			return
255		}
256		buf := &ycsbBuf{rng: randvar.NewRand()}
257	
258		b := db.NewBatch()
259		size := 0
260		start := time.Now()
261		last := start
262		for i := 1; i <= y.cfg.InitialKeys; i++ {
263			if now := time.Now(); now.Sub(last) >= time.Second {
264				fmt.Printf("%5s inserted %d keys (%0.1f%%)\n",
265					time.Duration(now.Sub(start).Seconds()+0.5)*time.Second,
266					i-1, 100*float64(i-1)/float64(y.cfg.InitialKeys))
267				last = now
268			}
269			if size >= 1<<20 {
270				if err := b.Commit(y.writeOpts); err != nil {
271					log.Fatal(err)
272				}
273				b = db.NewBatch()
274				size = 0
275			}
276			key := y.makeKey(uint64(i+y.cfg.PrepopulatedKeys), buf)
277			value := y.randBytes(buf)
278			if err := b.Set(key, value, nil); err != nil {
279				log.Fatal(err)
280			}
281			size += len(key) + len(value)
282		}
283		if err := b.Commit(y.writeOpts); err != nil {
284			log.Fatal(err)
285		}
286		fmt.Printf("inserted keys [%d-%d)\n",
287			1+y.cfg.PrepopulatedKeys,
288			1+y.cfg.PrepopulatedKeys+y.cfg.InitialKeys)
289	
290		// Flush so the resulting on-disk state is self-contained (no pending
291		// WAL); otherwise reopening the directory in read-only mode would fail.
292		if err := db.Flush(); err != nil {
293			log.Fatal(err)
294		}
295	
296		// Wait for compactions to stabilize.
297		fmt.Println("waiting for compactions to stabilize...")
298		m := db.Metrics()
299		for {
300			maxScore := 0.0
301			for i := range m.Levels {
302				maxScore = max(maxScore, m.Levels[i].Score)
303			}
304			if maxScore <= 1.05 && m.Compact.NumInProgress == 0 {
305				break
306			}
307			time.Sleep(250 * time.Millisecond)
308			m = db.Metrics()
309		}
310		fmt.Println(m.String())
311	}
