313	// run initializes derived state, starts the read-amp sampler (when
314	// applicable) and the worker goroutines on wg, then returns immediately.
315	func (y *ycsb) run(db DB, wg *sync.WaitGroup) {
316		y.db = db
317		y.keyNum = ackseq.New(uint64(y.cfg.InitialKeys + y.cfg.PrepopulatedKeys))
318		y.limiter = y.common.RateLimiter
319	
320		// If this workload doesn't produce reads, sample the worst case read-amp
321		// from Metrics() periodically.
322		if y.weights.get(ycsbRead) == 0 && y.weights.get(ycsbScan) == 0 && y.weights.get(ycsbReverseScan) == 0 {
323			wg.Go(func() { y.sampleReadAmp(db) })
324		}
325	
326		for range y.common.Concurrency {
327			wg.Go(func() { y.worker(db) })
328		}
329	}
