421	func (y *ycsb) insert(db DB, buf *ycsbBuf) {
422		count := y.batchDist.Uint64(buf.rng)
423		if cap(buf.keyNums) < int(count) {
424			buf.keyNums = make([]uint64, count)
425		}
426		keyNums := buf.keyNums[:count]
427	
428		b := db.NewBatch()
429		for i := range keyNums {
430			keyNums[i] = y.keyNum.Next()
431			_ = b.Set(y.makeKey(keyNums[i], buf), y.randBytes(buf), nil)
432		}
433		if err := b.Commit(y.writeOpts); err != nil {
434			log.Fatal(err)
435		}
436	
437		for i := range keyNums {
438			delta, err := y.keyNum.Ack(keyNums[i])
439			if err != nil {
440				log.Fatal(err)
441			}
442			if delta > 0 {
443				y.keyDist.IncMax(uint64(delta))
444			}
445		}
446	}
