449		key := y.nextReadKey(buf)
450		iter := db.NewIter(nil)
451		iter.SeekGE(key)
452		if iter.Valid() {
453			_ = iter.Key()
454			_ = iter.Value()
455		}
456	
457		type metrics interface {
458			Metrics() pebble.IteratorMetrics
459		}
460		if m, ok := iter.(metrics); ok {
461			y.readAmpCount.Add(1)
462			y.readAmpSum.Add(uint64(m.Metrics().ReadAmp))
463		}
464	
465		if err := iter.Close(); err != nil {
