 90	// RunTest runs the given Test against a freshly-opened Pebble DB at dir.
 91	func RunTest(dir string, common *CommonConfig, t Test) {
 92		if common.Wipe {
 93			fmt.Printf("wiping %s\n", dir)
 94			if err := os.RemoveAll(dir); err != nil {
 95				log.Fatal(err)
 96			}
 97		}
 98	
 99		fmt.Printf("dir %s\nconcurrency %d\n", dir, common.Concurrency)
100	
101		db := NewPebbleDB(dir, common)
102		t.Init(db)
103		var wg sync.WaitGroup
104		t.Run(db, &wg)
105	
106		ticker := time.NewTicker(time.Second)
107		defer ticker.Stop()
108	
109		done := make(chan os.Signal, 3)
110		workersDone := make(chan struct{})
111		signal.Notify(done, os.Interrupt)
112	
113		go func() {
114			wg.Wait()
115			close(workersDone)
116		}()
117	
118		if common.MaxSize > 0 {
119			go func() {
120				for {
121					time.Sleep(10 * time.Second)
122					if db.Metrics().DiskSpaceUsage() > common.MaxSize*1e6 {
123						fmt.Println("max size reached")
124						done <- syscall.Signal(0)
125					}
126				}
127			}()
128		}
129		if common.Duration > 0 {
130			go func() {
131				time.Sleep(common.Duration)
132				done <- syscall.Signal(0)
133			}()
134		}
