  13	// A RetryPolicy determines what error values should trigger a retry of an
  14	// operation.
  15	type RetryPolicy func(error) bool
  16	
  17	var (
  18		// NeverRetry implements a RetryPolicy that never retries.
  19		NeverRetry = func(error) bool { return false }
  20		// RetryInjected implements a RetryPolicy that retries whenever an
  21		// errorfs.ErrInjected error is returned.
  22		RetryInjected RetryPolicy = func(err error) bool {
  23			return errors.Is(err, errorfs.ErrInjected)
  24		}
  25	)
  26	
  27	func withRetries(fn func() error, retryPolicy RetryPolicy) error {
  28		for {
  29			if err := fn(); !retryPolicy(err) {
  30				return err
  31			}
  32		}
  33	}
