295	// Init initializes the merging iterator with the provided fragment iterators.
296	func (m *MergingIter) Init(
297		comparer *base.Comparer,
298		transformer keyspan.Transformer,
299		bufs *MergingBuffers,
300		iters ...keyspan.FragmentIterator,
301	) {
302		*m = MergingIter{
303			comparer:       comparer,
304			MergingBuffers: bufs,
305			transformer:    transformer,
306		}
307		m.heap.cmp = comparer.Compare
308		levels, items := m.levels, m.heap.items
309	
310		// Invariant: cap(levels) >= cap(items)
311		// Invariant: cap(alloc.levels) == cap(alloc.items)
312		if len(iters) <= len(m.alloc.levels) {
313			// The slices allocated on the MergingIter struct are large enough.
314			m.levels = m.alloc.levels[:len(iters)]
315			m.heap.items = m.alloc.items[:0]
316		} else if len(iters) <= cap(levels) {
317			// The existing heap-allocated slices are large enough, so reuse them.
318			m.levels = levels[:len(iters)]
319			m.heap.items = items[:0]
320		} else {
321			// Heap allocate new slices.
322			m.levels = make([]mergingIterLevel, len(iters))
323			m.heap.items = make([]mergingIterItem, 0, len(iters))
324		}
325		for i := range m.levels {
326			m.levels[i] = mergingIterLevel{iter: iters[i]}
327			if m.wrapFn != nil {
328				m.levels[i].iter = m.wrapFn(m.levels[i].iter)
329			}
330		}
